-- assessment_purpose
update public.fields set verification_status='verified_against_standard', verification_quote='Such an assessment may be carried out during operations or at the time of acquisition or divestiture of assets and may be conducted as part of a broader due diligence assessment process. — printed p.vi (PDF p.8)', verification_note='VA-verified 2026-09-08 (§0.1, printed p.vi (PDF p.8) — the four enum values (operations / acquisition / divestiture / broader_due_diligence) map 1:1 onto the four contexts this sentence names. CAVEAT: the sentence sits in the Introduction, which in an ISO deliverable is not a numbered normative clause, and it is permissive ("may"), so the field records a context, not an obligation) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='c7b86d1a-25cb-440e-90fa-d30a1b05e5e9' and verification_status not in ('verified_against_standard','corrected');
