update public.fields set verification_status='verified_against_standard', verification_quote='The assessor should confirm the physical boundaries of the asset and the limits of any associated operations in accordance with the assessment scope and plan. — printed p.13 (PDF p.23)', verification_note='VA-verified 2026-09-08 (§5.4.3, printed p.13 (PDF p.23) — the encoded clause_reference is "§1, §3.4"; Clause 1 (Scope) states no obligation to identify an asset and §3.4 is only the term definition, so the obligation actually rests on §5.4.3. Retag proposed in the STAGED file. Modality is "should", never "shall") [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='1de21901-696e-424e-9689-5fbd4e342389' and verification_status not in ('verified_against_standard','corrected');
