update public.fields set verification_status='verified_against_standard', verification_quote='This document is flexible in its application and may be used for self-assessments/internal to the organization as well as external assessments, with or without the need to employ third parties. — printed p.vi (PDF p.8)', verification_note='VA-verified 2026-09-08 (§0.2, printed p.vi (PDF p.8) — the two enum values (self_internal / external) are exactly the two the printed sentence names. CAVEAT: Introduction text, permissive ("may be used")) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='98808251-f2b4-462d-ae6b-8db04946d8a5' and verification_status not in ('verified_against_standard','corrected');
-- business_consequences_in_scope
update public.fields set verification_status='verified_against_standard', verification_quote='At the discretion of the client, the scope may include the determination of business consequences. | The determination of business consequences is only performed if it has been included in the objectives and scope of the assessment. — printed pp.9, 14 (PDF pp.19, 24)', verification_note='VA-verified 2026-09-08 (§5.3.3 + §5.5.3, printed pp.9, 14 (PDF pp.19, 24) — this field is the scope predicate for the whole ws-06 business-consequence branch. §3.11 Note 1 says the same ("optional, at the discretion of the client") but its text layer is OCR-corrupted at that point, so §5.3.3/§5.5.3 are quoted instead. Gate CR-027 does NOT read this predicate — see the STAGED file) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='2ef81485-8b7c-43f7-b435-fe2f7f5a48fc' and verification_status not in ('verified_against_standard','corrected');
