update public.fields set verification_status='verified_against_standard', verification_quote='Conclusions in an EDD assessment should be based on objective information. In the absence of verified and/or validated information, an EDD assessor can be required to exercise professional judgement in evaluating the available environmental information and drawing conclusions. — printed p.vii (PDF p.9)', verification_note='VA-verified 2026-09-08 (§0.3, printed p.vii (PDF p.9) — the two enum values (verified_validated_information / professional_judgement) are exactly the two bases this sentence names; §5.4.5 (printed p.14) repeats it, but the text layer of that page splits words ("o f", "a n"), so the Introduction wording is quoted) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='8e5fe5fe-7fab-4d8a-858e-fe879dcbed10' and verification_status not in ('verified_against_standard','corrected');
