update public.fields set verification_status='verified_against_standard', verification_quote='EDD assessment evidence should be verifiable and /or validated. It will, in general, be based on samples of the information available since EDD assessment activities are conducted during a finite period of time and with finite resources. An appropriate use of sampling should be applied, since this is closely related to the confidence that can be placed in the EDD assessment report. — printed p.5 (PDF p.15)', verification_note='VA-verified 2026-09-08 (§4.2.1, printed p.5 (PDF p.15) — quoted verbatim including the spacing artefact of the text layer, "and /or". Modality "should": gate CR-002 is correctly severity=warn) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='a5f0db2f-4956-42c1-9768-712424657cba' and verification_status not in ('verified_against_standard','corrected');
