update public.fields set verification_status='verified_against_standard', verification_quote='Where an external assessor is undertaking an EDD assessment on behalf of a client, roles and responsibilities should be established formally, considering the guidance provided in 5.2.2 to 5.2.4. Where an EDD assessment is undertaken internally, this guidance can assist. — printed p.6 (PDF p.16)', verification_note='VA-verified 2026-09-08 (§5.2.1, printed p.6 (PDF p.16) — note the obligation is scoped to an EXTERNAL assessor; for an internal assessment the standard only says the guidance "can assist". Gate CR-008 applies it unconditionally — see the STAGED file) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='7375d4b1-24bd-4f4c-90dc-c18ec51041af' and verification_status not in ('verified_against_standard','corrected');
