update public.fields set verification_status='verified_against_standard', verification_quote='The roles and responsibilities of assessment providers should be informed by ISO 19011 and include: | coordination and scheduling of assessments; | establishing assessment programmes, methodologies, checklists and protocols, as appropriate, for the scope of assessments undertaken; | ensuring assessors have the necessary competence for the activities undertaken (see Clause 7); | ensuring appropriate resources are provided for assessments; | ensuring appropriate assessment documented information is maintained. — printed p.8 (PDF p.18)', verification_note='VA-verified 2026-09-08 (§5.2.5, printed p.8 (PDF p.18) — the five printed bullets. NR caveat: the list is "informed by ISO 19011", a document not in the library; the ISO 19011 content itself is therefore not reachable and is not encoded) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='c0e84331-8e30-46e3-a5ff-a73940aa5422' and verification_status not in ('verified_against_standard','corrected');
