update public.fields set verification_status='verified_against_standard', verification_quote='The use of quantitative and qualitative methods should be suitably determined (defined), based on, among others, consideration of associated risks and opportunities. Sampling techniques can include judgement based or statistical sampling. — printed p.11 (PDF p.21)', verification_note='VA-verified 2026-09-08 (§5.3.6, printed p.11 (PDF p.21) — CAVEAT: "can include" is an open list; the two enum values are the only two the standard names but the list is not closed by the source) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='60565176-3786-4d5d-a8dc-46ae9e26c51d' and verification_status not in ('verified_against_standard','corrected');
-- assessment_plan_prepared
update public.fields set verification_status='verified_against_standard', verification_quote='The assessment plan should include the following, where applicable: | identification of the client, the representative of the assessee and the assessor(s); | assessment objectives and scope; | assessment criteria; | priority assessment areas; | roles and responsibilities; | working language of the assessment and associated reports; | assessment schedule, including dates and duration; | resources requirements (e.g. human, financial, technological); | reporting requirements; | confidentiality requirements. — printed p.11 (PDF p.21)', verification_note='VA-verified 2026-09-08 (§5.3.7, printed p.11 (PDF p.21) — the printed twelve-item list; two items ("outline of the assessment procedures to be used", "summary of the reference documents, checklists, protocols, and other working documents to be used") are elided for length and are not contradicted. Note "where applicable" — the list is conditional, not absolute) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='0fc1ff1c-209e-4f7d-9468-88635ddb350b' and verification_status not in ('verified_against_standard','corrected');
-- plan_approved_by_client
update public.fields set verification_status='verified_against_standard', verification_quote='The client should review and approve the assessment plan. The assessment plan should be communicated, if appropriate, to the representative of the assessee. — printed p.11 (PDF p.21)', verification_note='VA-verified 2026-09-08 (§5.3.7, printed p.11 (PDF p.21); §5.2.2 j) "approving the assessment plan" says the same on printed p.6) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='b83b42af-5387-4a09-bec6-856ebb24b337' and verification_status not in ('verified_against_standard','corrected');
-- objectives_defined
update public.fields set verification_status='verified_against_standard', verification_quote='The terms of the assessment should be confirmed with the assessor in context of broader due diligence requirements of the client. | The assessment should address the objectives specified by the client. — printed p.8 (PDF p.18)', verification_note='VA-verified 2026-09-08 (§5.3.2, printed p.8 (PDF p.18); §5.3.1 adds "Once it has been agreed that an assessment will be conducted, it should be planned.") [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='5e784f0c-a8e0-4639-970e-e4e8bc6a5d8e' and verification_status not in ('verified_against_standard','corrected');
-- scope_defined
update public.fields set verification_status='verified_against_standard', verification_quote='The scope establishes the boundaries and the focus of the assessment. | The scope of the assessment is subject to: | the available time and resources to complete the EDD assessment; | the nature of the objectives; | the nature and completeness of existing information; | the risk tolerance of the client; — printed p.9 (PDF p.19)', verification_note='VA-verified 2026-09-08 (§5.3.3, printed p.9 (PDF p.19) — quote trimmed after the fourth of six printed "subject to" bullets for length; the remaining two (relative priority of environmental risk; input of other interested parties) are not contradicted) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='2222e93f-18d1-49c1-92a0-da770830093a' and verification_status not in ('verified_against_standard','corrected');
-- scope_boundary_type
update public.fields set verification_status='verified_against_standard', verification_quote='physical boundaries of the assessee (e.g. site, part of a site); | organizational boundaries, including relationships with or activities involving contractors, suppliers, lessees, tenants, other organizations (e.g. for off-site waste disposal), individuals and former occupants; | any applicable virtual locations, e.g. virtual data rooms; — printed p.9 (PDF p.19)', verification_note='VA-verified 2026-09-08 (§5.3.3, printed p.9 (PDF p.19) — the three enum values (physical / organizational / virtual) are exactly these three printed bullets of the "to determine the scope ... the following should be considered" list) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='a1460d5c-cf62-418c-b5b5-9ab38745e9e2' and verification_status not in ('verified_against_standard','corrected');
-- scope_change_recorded
update public.fields set verification_status='verified_against_standard', verification_quote='The scope may establish or limit any related assets to be included in the assessment. At the discretion of the client, the scope may be amended after the assessment has begun. Any change should be recorded and communicated to the relevant parties. — printed p.10 (PDF p.20)', verification_note='VA-verified 2026-09-08 (§5.3.3, printed p.10 (PDF p.20) — FINDING: the printed obligation is CONDITIONAL on a change having occurred ("Any change should be recorded"). Gate CR-013 demands scope_change_recorded == True unconditionally, so an assessment whose scope never changed can only pass by answering untruthfully. STAGED) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='302fe2bf-439d-426f-974b-f0aa2271b656' and verification_status not in ('verified_against_standard','corrected');
-- priority_areas_identified
update public.fields set verification_status='verified_against_standard', verification_quote='determining priority assessment areas, if appropriate; | Priorities are typically established on the basis of information available while planning the assessment. The identification of priorities does not exempt the assessor from the obligation of taking into account the full scope during the assessment. — printed pp.6, 10 (PDF pp.16, 20)', verification_note='VA-verified 2026-09-08 (§5.2.2 h) + §5.3.3, printed pp.6, 10 (PDF pp.16, 20) — the §5.3.3 sentence that opens this passage ("The client may identify elements within the established scope...") is OCR-merged in the text layer as "identifyelements", so it is not quoted; is_required=false is correct ("if appropriate")) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='cedf1b7a-1c6a-408f-bee7-3b123a25166a' and verification_status not in ('verified_against_standard','corrected');
-- ================ ISO-14015-05 ================
-- information_gathered
update public.fields set verification_status='verified_against_standard', verification_quote='The process of gathering information on environmental aspects should be consistent with the objectives, scope and assessment plans. While gathering information, the assessor should ensure that it is sufficient, relevant and accurate for the purpose of the assessment. — printed p.12 (PDF p.22)', verification_note='VA-verified 2026-09-08 (§5.4.1, printed p.12 (PDF p.22)) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='c94a1a72-3933-4905-af4a-f6fcedb3eca6' and verification_status not in ('verified_against_standard','corrected');
-- documents_reviewed
update public.fields set verification_status='verified_against_standard', verification_quote='The assessor should collect and review documents and records to obtain a sufficient understanding of the asset, without unnecessarily duplicating prior investigative efforts. | Multiple sources of information should be reviewed to corroborate any specific finding. — printed p.12 (PDF p.22)', verification_note='VA-verified 2026-09-08 (§5.4.2, printed p.12 (PDF p.22) — the document/source examples themselves live in Annex A, which is marked (informative)) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='8215b7b3-f247-4651-95cc-937a84c56ef1' and verification_status not in ('verified_against_standard','corrected');
-- working_papers_maintained
update public.fields set verification_status='verified_against_standard', verification_quote='The assessor should maintain working papers to support the information-gathering process. During the gathering and review of information, it is important that the assessor record the type, source, quality and reliability of the information. — printed p.12 (PDF p.22)', verification_note='VA-verified 2026-09-08 (§5.4.2, printed p.12 (PDF p.22)) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='323898fa-0b25-4e2e-9a46-e41d405c8ff0' and verification_status not in ('verified_against_standard','corrected');
-- activities_observed
update public.fields set verification_status='verified_against_standard', verification_quote='The assessor should observe and record information regarding the physical attributes and condition of the asset due to past activities and current operations. | The assessor should, where practicable, support observations with photographic and/or written records in accordance with the assessment plan. — printed p.12 (PDF p.22)', verification_note='VA-verified 2026-09-08 (§5.4.3, printed p.12 (PDF p.22) — note the "where practicable" qualifier on the second sentence; gate CR-021 applies the field unconditionally) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='a03c09a7-2607-458d-8cbf-100fcbefa545' and verification_status not in ('verified_against_standard','corrected');
-- observation_category
update public.fields set verification_status='verified_against_standard', verification_quote='activities; | materials and properties; | attributes and conditions of the asset; | attributes and conditions of the surroundings. — printed p.12 (PDF p.22)', verification_note='VA-verified 2026-09-08 (§5.4.3, printed p.12 (PDF p.22) — the four enum values are exactly the four printed categories. The sentence that introduces them cross-references the annex, but the text layer renders "Annex B" as "Annex 8" (OCR), so that run is excluded from the quote under SR-3. CAVEAT: the element examples themselves sit in Annex B, marked (informative)) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='4eb9b004-0d3e-4f63-bd87-0c8e2d865a0d' and verification_status not in ('verified_against_standard','corrected');
-- access_limitation_recorded
update public.fields set verification_status='verified_against_standard', verification_quote='Where asset access is limited, the assessor should also attempt to use other possible sources to accomplish physical condition observations, such as using aerial photos, geographic information system (GIS) remote sensors, online research/search techniques and fence line observation. | Where the assessor is unable to gain access to any part of the asset subject to the assessment, this limitation should be recorded in the assessment report. — printed p.13 (PDF p.23)', verification_note='VA-verified 2026-09-08 (§5.4.3, printed p.13 (PDF p.23) — is_required=false is correct: the obligation is conditional ("Where the assessor is unable to gain access")) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='d0c04f24-1d36-4b11-9c3b-de92623fae94' and verification_status not in ('verified_against_standard','corrected');
-- safety_requirements_followed
update public.fields set verification_status='verified_against_standard', verification_quote='The assessor should follow all applicable safety requirements when visiting/inspecting the asset. — printed p.13 (PDF p.23)', verification_note='VA-verified 2026-09-08 (§5.4.3, printed p.13 (PDF p.23) — identical to the encode-time source_quote on gate CR-022. FINDING: the printed obligation is scoped to "when visiting/inspecting the asset"; CR-022 has no such predicate even though remote_assessment_used exists. STAGED) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='bd8ed115-69f3-4c49-b1cb-75016ddccb84' and verification_status not in ('verified_against_standard','corrected');
-- interviews_conducted
update public.fields set verification_status='verified_against_standard', verification_quote='The interview is a means of collecting information to corroborate or augment information derived from examining existing documents and records and observing physical conditions and activities. | With the approval of the client and of the representative of the assessee, assessee personnel responsible for or engaged in the activities and processes being assessed may be interviewed. — printed p.13 (PDF p.23)', verification_note='VA-verified 2026-09-08 (§5.4.4.1 + §5.4.4.2, printed p.13 (PDF p.23) — FINDING: interviewing is permissive throughout ("may be interviewed"), yet gate CR-023 demands interviews_conducted == True unconditionally. STAGED) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='cacc0c0a-3c37-48e3-b853-177a30676442' and verification_status not in ('verified_against_standard','corrected');
-- interviewee_category
update public.fields set verification_status='verified_against_standard', verification_quote='Examples of various internal, associated or external interviewee categories are provided in Annex C. — printed p.13 (PDF p.23)', verification_note='VA-verified 2026-09-08 (§5.4.4.2, printed p.13 (PDF p.23) — the three enum values are exactly the three printed category names. CAVEAT: the members of each category are listed only in Annex C, which is marked (informative)) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='8ca89642-7e6b-4d66-949c-ca40fa2c9194' and verification_status not in ('verified_against_standard','corrected');
-- information_verified_validated
update public.fields set verification_status='verified_against_standard', verification_quote='As the information is gathered, it should be verified and/or validated for accuracy, reliability, sufficiency and appropriateness for the purposes of meeting the assessment objectives. — printed p.13 (PDF p.23)', verification_note='VA-verified 2026-09-08 (§5.4.5, printed p.13 (PDF p.23); the terms themselves are defined at §3.21 (validation) and §3.22 (verification), printed p.4) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='48aad03a-ccfb-44e4-a5bb-ce2f2803d9ba' and verification_status not in ('verified_against_standard','corrected');
-- information_limitations_communicated
update public.fields set verification_status='verified_against_standard', verification_quote='The consequences of any information limitations should be determined and communicated to the client to determine the effects on the assessment. | If information of value is collected that is outside the scope of the assessment but can contribute to meeting the objectives of the assessment, it should be communicated to the client. — printed p.13 (PDF p.23)', verification_note='VA-verified 2026-09-08 (§5.4.5, printed p.13 (PDF p.23)) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='3a3a93a5-5295-462f-a16d-682a36deb216' and verification_status not in ('verified_against_standard','corrected');
-- ================ ISO-14015-06 ================
-- environmental_issues_identified
update public.fields set verification_status='verified_against_standard', verification_quote='Environmental issues are identified by comparison of the verified and/or validated information with the selected criteria and can result in identification of: | liabilities or benefits to the organization; | effects on the assessee''s or the client''s public image; | other risks and opportunities. — printed p.14 (PDF p.24)', verification_note='VA-verified 2026-09-08 (§5.5.2, printed p.14 (PDF p.24); the term itself is defined at §3.13, printed p.3) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='3d0a8379-a0a3-48e5-89be-2e00c5942049' and verification_status not in ('verified_against_standard','corrected');
-- environmental_issue_outcome
update public.fields set verification_status='verified_against_standard', verification_quote='liabilities or benefits to the organization; | effects on the assessee''s or the client''s public image; | other risks and opportunities. | Issues that can be less relevant from a business perspective can be environmentally relevant, and vice versa. — printed p.14 (PDF p.24)', verification_note='VA-verified 2026-09-08 (§5.5.2, printed p.14 (PDF p.24) — the five enum values split the three printed outcome bullets (liability/benefit from bullet 1, public_image_effect from bullet 2, risk/opportunity from bullet 3). The split is granularity added by EKOWAI, not wording of the standard; the domain is not widened by it) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='ab9894b3-f42a-4c67-9d78-237da7bf5d7f' and verification_status not in ('verified_against_standard','corrected');
-- business_consequences_determined
update public.fields set verification_status='verified_against_standard', verification_quote='The determination of business consequences is only performed if it has been included in the objectives and scope of the assessment. | Business consequences (e.g. strategic, operational, economic or financial) are the actual or potential impacts (e.g. positive or negative, qualitative or quantitative, of internal or external appearance, monetized or non-monetized) of the identified and evaluated environmental issues. — printed p.14 (PDF p.24)', verification_note='VA-verified 2026-09-08 (§5.5.3, printed p.14 (PDF p.24) — FINDING: the printed sentence makes this step conditional on business_consequences_in_scope, but gate CR-027 demands business_consequences_determined == True with no scope predicate. STAGED) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='b7654f7d-901f-458a-9488-e5de9991abf5' and verification_status not in ('verified_against_standard','corrected');
-- consequence_judgement_factor
update public.fields set verification_status='verified_against_standard', verification_quote='In exercising judgement, the following may be considered: | environmental damage; | the scope of the affected asset; | damage to assessee''s and/or client''s reputation; | environmental improvements; | intellectual property that supports future sustainability of the organization; | estimated costs of taking such measures or actions; | technological developments and limitations; — printed pp.14, 15 (PDF pp.24, 25)', verification_note='VA-verified 2026-09-08 (§5.5.3, printed pp.14-15 (PDF pp.24-25) — the ten enum values are the ten printed bullets; the quote is fragmented because the printed list runs across a page break and two long bullets (current/future risks; policy nonconformance) are elided for length. CAVEAT: the list is permissive ("may be considered")) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='ee6da654-e0eb-44fd-93f1-ab9c7e3ec21f' and verification_status not in ('verified_against_standard','corrected');
-- ================ ISO-14015-07 ================
-- report_provided
update public.fields set verification_status='verified_against_standard', verification_quote='The assessor has responsibility for the content of the report and should present information in a manner designed to help the client understand the significance of the findings. | The EDD assessment report should be provided as documented information. — printed pp.15, 16 (PDF pp.25, 26)', verification_note='VA-verified 2026-09-08 (§6.1, printed pp.15-16 (PDF pp.25-26)) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='c9eb40d6-4508-4b66-b1da-686e851dfeea' and verification_status not in ('verified_against_standard','corrected');
-- mandatory_content_included
update public.fields set verification_status='verified_against_standard', verification_quote='The following information should be reported to the client: | identification of the projects, assets or activities of the organization which has been assessed; | assessment objectives, scope and criteria; | dates and duration of the assessment; | any limitations of the available information and its consequences on the assessment; | any limitations, exclusions, amendments and deviations from the agreed scope of the assessment; | summary of the information collected during the assessment and the results of the assessment. — printed p.15 (PDF p.25)', verification_note='VA-verified 2026-09-08 (§6.1, printed p.15 (PDF p.25) — the printed seven-item "should be reported" list; the second item ("name(s) of the assessor (s) and author of the report") is elided for length. A SECOND, longer list on the same page is introduced with "the following information may also be reported" — the field label "Pflichtinhalte" refers only to the first, "should", list, which is correct) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='a0940394-370e-4cf2-a50c-04ab09bc0a38' and verification_status not in ('verified_against_standard','corrected');
-- findings_qualified
update public.fields set verification_status='verified_against_standard', verification_quote='Where conclusions are restricted because of insufficient information, this should be stated and any finding should be qualified accordingly. | The assessor should qualify any findings for which limitations exist, e.g. because of insufficient information. — printed pp.15, 16 (PDF pp.25, 26)', verification_note='VA-verified 2026-09-08 (§5.5.3 (closing) + §6.1, printed pp.15-16 (PDF pp.25-26)) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='875a0ce3-e992-429a-bfc4-1c3aea1acdc1' and verification_status not in ('verified_against_standard','corrected');
-- report_distribution_controlled
update public.fields set verification_status='verified_against_standard', verification_quote='Reports are the sole property of the client. Confidentiality should therefore be respected and appropriately safeguarded by the assessor (s) and any report recipients. Distribution of the report is at the discretion of the client. — printed p.16 (PDF p.26)', verification_note='VA-verified 2026-09-08 (§6.2, printed p.16 (PDF p.26) — identical to the encode-time source_quote on gate CR-031; quoted verbatim including the spacing artefact of the text layer, "assessor (s)") [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='ed235ba9-9619-4c9e-85b3-58e43c46dfe5' and verification_status not in ('verified_against_standard','corrected');
-- ================ ISO-14015-08 ================
-- prerequisite_skills_present
update public.fields set verification_status='verified_against_standard', verification_quote='All individuals undertaking EDD assessment activity have the necessary competencies as set out in Table 1 and the following prerequisite skills: | language appropriate to all levels within the client organization; | note-taking and report-writing; | presentation; | information, communication and technology; — printed p.16 (PDF p.26)', verification_note='VA-verified 2026-09-08 (§7.1, printed p.16 (PDF p.26) — the fifth printed skill ("interviewing") is OCR-split in the text layer as "interview ing" and is therefore not quoted. NOTE: this is one of the very few flat-indicative statements in the document ("have the necessary competencies"), yet still not a "shall") [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='6ed8c9b9-7856-4e72-89a0-e663048ebaf0' and verification_status not in ('verified_against_standard','corrected');
-- competence_process_applied
update public.fields set verification_status='verified_against_standard', verification_quote='A suitable process should be applied for determining the competence needed for persons involved in the management and performance of EDD assessment activity. | Competence should be demonstrated prior to the individual taking responsibility for the performance of their activities of a particular EDD assessment. — printed p.17 (PDF p.27)', verification_note='VA-verified 2026-09-08 (§7.2, printed p.17 (PDF p.27)) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='ed4bac7f-7b5d-4547-b528-45de50b01ec0' and verification_status not in ('verified_against_standard','corrected');
-- competence_area
update public.fields set verification_status='verified_against_standard', verification_quote='Table 1 lists the areas of competence applicable generically to the management and performance of EDD assessment activities. It also indicates where there can be specific competencies relevant to the performance of a particular EDD assessment. | Table 1 - Competence for managing and performing EDD assessment activities — printed p.17 (PDF p.27)', verification_note='VA-verified 2026-09-08 (§7.2 + the Table 1 caption, printed p.17 (PDF p.27) — the twelve enum values map 1:1 onto the twelve rows of Table 1 as printed across pp.17-18 (nine rows on p.17, three on p.18); the row texts themselves are not quoted because the two-column x-mark layout is reflowed by the extractor) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='19dc742b-261f-44aa-b095-a0dbe0d3508e' and verification_status not in ('verified_against_standard','corrected');
-- competence_class
update public.fields set verification_status='verified_against_standard', verification_quote='Each assessor within an assessment team should possess the generic set of competencies. Any necessary specific competencies should be possessed by at least one member of the assessment team. An assessment team can be composed of one or several persons. — printed p.17 (PDF p.27)', verification_note='VA-verified 2026-09-08 (§7.2, printed p.17 (PDF p.27) — the two enum values (generic / specific) are exactly the two Table 1 columns, and this sentence states what each means) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='fcd8cca5-793f-4f77-b408-f80e2cfe4e24' and verification_status not in ('verified_against_standard','corrected');
-- competence_evaluation_documented
update public.fields set verification_status='verified_against_standard', verification_quote='The evaluation of assessor competence should be planned, implemented and documented to provide an outcome that is objective, consistent, fair and reliable. The evaluation process should be informed by ISO 19011 and include four main steps, as follows: | a) determine the required competence to fulfil the needs of the assessment programme; | b) establish the evaluation criteria; | c) select the appropriate evaluation method; | d) conduct the evaluation. — printed p.18 (PDF p.28)', verification_note='VA-verified 2026-09-08 (§7.3, printed p.18 (PDF p.28) — NR caveat: the process is "informed by ISO 19011", a document not in the library) [VA · BS EN ISO 14015:2022 published (identical to ISO 14015:2022, 2nd edition), PDF text layer]', verified_at=now() where id='775ae90c-51b0-4a21-9b67-e569e9a25671' and verification_status not in ('verified_against_standard','corrected');

-- equations: none exist for ISO-14015 (0 rows in prod) and the source prints no formula - nothing to write.
